"""v3.5: reading and reach. Type a person can read aloud from, a text size control, rooms and exits that can be
reached without a mouse, messages a screen reader hears, plain headings, sound offered once, the Overview in the
order of play, and a player's screen that no longer names creatures before the game master has. The dungeon
generator is not touched."""
import sys; sys.path.insert(0, __file__.rsplit('/', 1)[0])
from patchlib import Patch
p = Patch(sys.argv[1])

# ---- version ----
p.rep('<span class="ver">v3.4</span>', '<span class="ver">v3.5</span>')
p.rep('· v3.4 · build 2026-11-09 ·', '· v3.5 · build 2026-11-09 ·')
p.rep('Generated by Abyssal Cartographer v3.4. Seed: ', 'Generated by Abyssal Cartographer v3.5. Dungeon code: ')
p.rep('Made with Abyssal Cartographer v3.4. ', 'Made with Abyssal Cartographer v3.5. ')

# ---- type: a floor of about 12.5 px, and read-aloud text you can read aloud from ----
for old, new in [
  ('font-family:system-ui,-apple-system,"Segoe UI",sans-serif; font-size:14px;', 'font-family:system-ui,-apple-system,"Segoe UI",sans-serif; font-size:15px;'),
  ('border-radius:3px; padding:11px 13px;\n  font-style:italic; line-height:1.5; font-size:13.5px; position:relative;', 'border-radius:3px; padding:13px 16px;\n  font-style:normal; line-height:1.6; font-size:17px; position:relative;'),
  ('.dun-sub{font-size:12px;', '.dun-sub{font-size:13px;'),
  ('.klabel{font-size:10.5px;', '.klabel{font-size:11.5px;'),
  ('.card .meta{font-size:11.5px;', '.card .meta{font-size:13px;'),
  ('padding:9px 11px; margin:8px 0; font-size:12.5px; line-height:1.5}', 'padding:9px 11px; margin:8px 0; font-size:13.5px; line-height:1.5}'),
  ('.statblock .mflavor{font-style:italic; color:var(--parch-dim); font-size:12px;', '.statblock .mflavor{font-style:italic; color:var(--parch-dim); font-size:13px;'),
  ('.statblock .mline{font-family:ui-monospace,monospace; font-size:11.5px;', '.statblock .mline{font-family:ui-monospace,monospace; font-size:13px;'),
  ('.pill{display:inline-block; font-size:10.5px;', '.pill{display:inline-block; font-size:11.5px;'),
  ('.rtags{font-size:10.5px;', '.rtags{font-size:11.5px;'),
  ('.exitline{font-size:12.5px; margin:2px 0}', '.exitline{font-size:14px; margin:3px 0}'),
  ('.secretline{color:var(--cold); font-size:12.5px}', '.secretline{color:var(--cold); font-size:13.5px}'),
  ('.dmnote{font-size:13px;', '.dmnote{font-size:14px;'),
  ('.treas{font-size:12.5px}', '.treas{font-size:13.5px}'),
  ('gap:2px 10px; font-size:12px; color:var(--parch-dim); margin-top:7px}', 'gap:2px 10px; font-size:13.5px; color:var(--parch-dim); margin-top:7px}'),
  ('.senses b{color:var(--parch-deep); font-weight:600; font-size:10.5px;', '.senses b{color:var(--parch-deep); font-weight:600; font-size:11px;'),
  ('.tiny{font-size:11px; color:var(--parch-deep)}', '.tiny{font-size:13px; color:var(--parch-dim)}'),
  ('border-bottom:1px dashed var(--line); font-size:13px;', 'border-bottom:1px dashed var(--line); font-size:14px;'),
  ('.frow .hint{display:block; font-size:11px;', '.frow .hint{display:block; font-size:12px;'),
  ('border-radius:0; padding:9px 4px; font-size:12.5px;', 'border-radius:0; padding:9px 4px; font-size:13.5px;'),
  ('#mapHint{position:absolute; bottom:10px; left:12px; font-size:11.5px;', '#mapHint{position:absolute; bottom:10px; left:12px; font-size:12.5px;'),
  ('.gmsteps .step{display:flex; gap:10px; margin:9px 0; font-size:13px;', '.gmsteps .step{display:flex; gap:10px; margin:9px 0; font-size:14px;'),
  ('.door .sub{font-size:12.5px;', '.door .sub{font-size:13.5px;'),
  ('.door button small{display:block; font-size:12px;', '.door button small{display:block; font-size:13px;'),
  ('#sidebar{flex:1; min-width:340px; max-width:520px;', '#sidebar{flex:1; min-width:340px; max-width:580px;'),
  ('.readbtn{font-size:11px; padding:2px 8px;', '.readbtn{font-size:12.5px; padding:3px 10px;'),
  ('.qplain{font-family:"Iowan Old Style",Palatino,Georgia,serif; font-style:italic; font-size:12.5px;', '.qplain{font-family:"Iowan Old Style",Palatino,Georgia,serif; font-style:italic; font-size:14.5px;'),
  ('#torchState{font-size:12px; color:var(--parch-dim); max-width:340px; line-height:1.35}', '#torchState{font-size:13px; color:var(--parch-dim); max-width:360px; line-height:1.35}'),
  ('#mapTools button{background:rgba(26,23,20,.88); font-size:12px;', '#mapTools button{background:rgba(26,23,20,.88); font-size:13px;'),
  ('.door{position:absolute; left:50%; top:44%;', '.door{position:fixed; left:50%; top:46%;'),
  ('.rumor .truth{font-size:10.5px;', '.rumor .truth{font-size:11.5px;'),
  ('.brand .ver{font-size:11px;', '.brand .ver{font-size:11.5px;'),
  ('.seedbox .seedlab{font-size:11px;', '.seedbox .seedlab{font-size:12px;'),
  ('.boxed{border:1px solid #8f8266;background:#efe6d0;padding:10px 13px;font-style:italic;margin:8px 0;border-radius:2px}', '.boxed{border:1px solid #8f8266;background:#efe6d0;padding:11px 14px;font-style:normal;font-size:15px;line-height:1.6;margin:8px 0;border-radius:2px}'),
]: p.rep(old, new)

p.before("/* ---------- the player's table ---------- */\nbody.choosing #sidebar", '''/* ---------- reading and reach ---------- */
#tabBody, .qsheet{zoom:var(--tz,1)}
#mapSvg .roomG:focus-visible, #mapSvg .frontier:focus-visible{outline:2px solid var(--accent); outline-offset:3px}
.rrow:focus-visible, .exitline[role=button]:focus-visible{outline:2px solid var(--accent); outline-offset:1px}
.exitline[role=button]{cursor:pointer}
.exitline[role=button]:hover{color:var(--flame)}
.doorlede{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif; font-size:15.5px; color:var(--parch); margin-bottom:10px; line-height:1.4}
.doorsound{display:flex; gap:8px; align-items:flex-start; font-size:13px; color:var(--parch-dim); margin-top:10px; cursor:pointer; line-height:1.35}
.doorsound input{accent-color:var(--torch); margin-top:3px}
#sndOffer{font-size:12px; padding:3px 9px}
body.dark .darkbanner{flex:1 1 100%; margin-left:0}
header{z-index:45} /* its menus open over the folded note and the first-visit card */
#soundMenu{z-index:46; max-height:calc(100vh - 70px); overflow-y:auto}
@media (max-width:700px){ button, select{min-height:40px} .tabs button{min-height:44px} .toast{top:10px; bottom:auto} }
''')

# ---- things a screen reader and a keyboard can reach ----
p.rep('<svg id="mapSvg" role="img" aria-label="Dungeon map"></svg>', '<svg id="mapSvg" role="group" aria-label="Dungeon map. Tab moves between rooms and doorways; Enter chooses one."></svg>')
p.rep('<div class="toast" id="toast"></div>', '<div class="toast" id="toast" role="status" aria-live="polite"></div>')
p.rep('<div class="qsheet" id="qSheet"></div>', '<div class="qsheet" id="qSheet" role="dialog" aria-modal="true" aria-label="A letter, and your first game"></div>')
p.rep('''parts.push('<g class="roomG" data-room="'+r.id+'" opacity="'+(dim?0.3:1)+'" style="cursor:pointer">');''',
      '''parts.push('<g class="roomG" data-room="'+r.id+'" opacity="'+(dim?0.3:1)+'" style="cursor:pointer"'+(opts.print?'':' tabindex="0" role="button" aria-label="Room '+(r.id+1)+', '+esc(r.name)+(isRev?'':', not yet lit')+'"')+'>');''')
p.rep('''parts.push('<circle class="frontier" data-goto="'+far+'"''', '''parts.push('<circle class="frontier" tabindex="0" role="button" aria-label="A doorway beyond the light" data-goto="'+far+'"''')
p.rep('''function reveal(id){const was=S.revealed.has(id)''', '''$("#mapSvg").addEventListener("keydown",e=>{ /* the map without a mouse: Enter or Space on a room or a doorway */
  if(e.key!=="Enter"&&e.key!==" ")return; const t=e.target&&e.target.closest?e.target.closest(".frontier,.roomG"):null; if(!t)return; e.preventDefault();
  let id; if(t.classList.contains("frontier")){id=+t.dataset.goto;reveal(id);} else{id=+t.dataset.room; if(S.revealed.has(id)||S.view==="dm")select(id); else return;}
  requestAnimationFrame(()=>{const g=document.querySelector('#mapSvg .roomG[data-room="'+id+'"]'); if(g)g.focus();});});
function reveal(id){const was=S.revealed.has(id)''')
p.rep('''h+='<div class="exitline">'+(x.secret?''', '''h+='<div class="exitline"'+((dm||S.revealed.has(x.to-1))?' data-goto-room="'+(x.to-1)+'" title="Go to room '+x.to+'"':'')+'>'+(x.secret?''')
p.rep('''    renderFoot();if(S.tab==="loot")renderPanel();}));\n''', '''    renderFoot();if(S.tab==="loot")renderPanel();}));
  /* rooms in a list and exits in a room can be reached and chosen without a mouse */
  const onOver=S.tab==="over";
  el.querySelectorAll("[data-goto-room]").forEach(x=>{x.setAttribute("tabindex","0");x.setAttribute("role","button");
    if(!onOver)x.addEventListener("click",()=>select(+x.dataset.gotoRoom));
    x.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();select(+x.dataset.gotoRoom);}});});
''')
p.rep('''document.addEventListener("keydown",function(e){if(e.key==="Escape")qClose();});''', '''document.addEventListener("keydown",function(e){if(e.key==="Escape")qClose();});
document.addEventListener("keydown",function(e){ /* Escape closes whatever is open */
  if(e.key!=="Escape")return;
  var x=document.getElementById("exportMenu"); if(x)x.classList.remove("open");
  var c=document.getElementById("configOverlay"); if(c)c.classList.remove("open");
  var t=document.getElementById("tblHelp"); if(t)t.classList.remove("open");
  var m=document.getElementById("soundMenu"), b=document.getElementById("btnSound");
  if(m&&m.classList.contains("open")&&!(typeof sndTalking==="function"&&sndTalking())){m.classList.remove("open"); if(b)b.setAttribute("aria-expanded","false");}
});''')
p.rep('''$("#btnConfig").addEventListener("click",()=>$("#configOverlay").classList.add("open"));''',
      '''$("#btnConfig").addEventListener("click",()=>{$("#configOverlay").classList.add("open");setTimeout(()=>{const f=$("#textSize button.on")||$("#cfgParty");if(f)f.focus();},30);});
/* text size: a zoom on the reading panel and the letter, kept between visits */
function setTextSize(z,quiet){z=+z||1;document.documentElement.style.setProperty("--tz",z);
  document.querySelectorAll("#textSize button").forEach(b=>b.classList.toggle("on",+b.dataset.tz===z));
  if(!quiet){try{localStorage.setItem("ac.text",String(z));}catch(e){}}}
$("#textSize").addEventListener("click",e=>{const b=e.target.closest("button");if(b)setTextSize(b.dataset.tz);});
try{const z=+localStorage.getItem("ac.text");if(z)setTextSize(z,true);}catch(e){}''')

# ---- plain headings first, flavor second; one word for each thing ----
p.rep('<div class="sheet">\n    <h2 class="smallcaps">Expedition terms</h2>',
      '<div class="sheet" role="dialog" aria-modal="true" aria-label="Settings">\n    <h2>Settings</h2>\n'
      '    <div class="frow"><label>Text size<span class="hint">Changes at once. It does not rebuild the dungeon.</span></label>'
      '<div class="toggle" id="textSize" role="group" aria-label="Text size"><button data-tz="1" class="on">Regular</button><button data-tz="1.15">Large</button><button data-tz="1.3">Larger</button></div></div>\n'
      '    <div class="klabel">The next dungeon: the terms of the expedition</div>')
p.rep('Seal the terms &amp; generate', 'Build a new dungeon with these settings')
p.rep('<span class="seedlab qterm" data-q="seed" id="seedLabel">seed</span>', '<span class="seedlab qterm" data-q="seed" id="seedLabel">dungeon code</span>')
p.rep('aria-label="Dungeon seed"', 'aria-label="Dungeon code"')
p.rep('''seed:["The seed","A dungeon's short identity code, its true name. Put the same code in''', '''seed:["The dungeon code","Each dungeon has a short code that is its true name. Put the same code in''')
p.rep('or paste a seed to rebuild a specific dungeon.', 'or paste a dungeon code to rebuild that dungeon.', count=2)
p.rep('"Link copied. Same seed, same dungeon, same secrets."', '"Link copied. Same code, same dungeon, same secrets."')
p.rep("""' · depth '+m.depth+' · seed '+esc(m.seed)+'</div>'""", """' · depth '+m.depth+' · code '+esc(m.seed)+'</div>'""")
p.rep('''" · depth "+m.depth+" · seed "+m.seed''', '''" · depth "+m.depth+" · code "+m.seed''')
p.rep('It needs a brain: an account key you already pay for, or a model running on this computer.', 'It needs an AI to do the talking: an account key you already pay for, or a model running on this computer.')
p.rep('<label>Where the brain is</label>', '<label>Where the AI runs</label>')
p.rep('(choose it under <b>Where the brain is</b>)', '(choose it under <b>Where the AI runs</b>)', count=2)
p.rep('bookmark this page (it remembers which rooms are lit) and go back to the same chat.', 'bookmark this page (it remembers which rooms are lit and where your torch stood) and go back to the same chat.')

# ---- a player's screen does not name the creatures before the game master has ----
p.rep('if(r.enc&&(dm||S.revealed.has(r.id))){', 'if(r.enc&&(dm||(S.revealed.has(r.id)&&S.role!=="player"))){')

# ---- the first screen says what this is, and offers sound once ----
p.rep('''d.innerHTML='<h3>Are you playing, or running the game?</h3><div class="sub">A dungeon is already drawn behind this card. Your choice decides how much of it you get to see.</div>\'''',
      '''d.innerHTML='<div class="doorlede">One click builds a whole dungeon adventure. This one is already drawn, behind this card.</div><h3>Are you playing, or running the game?</h3><div class="sub">Your choice decides how much of it you get to see.</div>\'''')
p.rep('''<small>You hold the map and every secret: the full game master’s screen.</small></button>';''',
      '''<small>You hold the map and every secret: the full game master’s screen.</small></button>'
    +'<label class="doorsound"><input type="checkbox" id="doorSound"><span>With sound: dripping water, doors, footsteps and your torch. Nothing to download. The Sound button has voices too.</span></label>';''')
p.rep('''  pane.appendChild(d);
  $("#doorPlayer").addEventListener("click",()=>{d.remove();setRole("player",{sys:"5e"});});
  $("#doorDM").addEventListener("click",()=>{d.remove();setRole("dm");setTimeout(qDropNote,600);});''',
      '''  pane.appendChild(d); setTimeout(()=>{const b=$("#doorPlayer");if(b)b.focus();},60);
  const wantSound=()=>{const c=$("#doorSound"); if(c&&c.checked)sndTurnOn(); try{localStorage.setItem("ac.sndOffered","1");}catch(e){}};
  $("#doorPlayer").addEventListener("click",()=>{wantSound();d.remove();setRole("player",{sys:"5e"});});
  $("#doorDM").addEventListener("click",()=>{wantSound();d.remove();setRole("dm");setTimeout(qDropNote,600);});''')
p.before('function roleDoor(){', '''/* sound is offered, never sprung: once at the door, and once more the first time a torch is lit */
function sndTurnOn(){SND.cfg.room=true;SND.cfg.cues=true;sndSave();try{sndCtx();sndTick();}catch(e){}}
function sndOfferOnce(){
  if(TBL.isTable||SND.cfg.room||SND.cfg.cues||SND.cfg.voice||document.getElementById("sndOffer"))return;
  try{if(localStorage.getItem("ac.sndOffered"))return;localStorage.setItem("ac.sndOffered","1");}catch(e){return;}
  const row=document.querySelector(".torchbtns"); if(!row)return;
  const b=document.createElement("button"); b.id="sndOffer"; b.textContent="♪ Hear the dungeon?"; b.title="Turns on room sounds and small cues. Nothing downloads.";
  b.addEventListener("click",()=>{sndTurnOn();b.remove();toast("Sound is on. The Sound button at the top has voices and levels.",4200);});
  row.appendChild(b); setTimeout(()=>{if(b.isConnected)b.remove();},90000);
}
''')
p.rep('''narAnnounce($("#torchState").textContent);\n  renderTorch();renderLight();torchSave();\n}''', '''narAnnounce($("#torchState").textContent);\n  renderTorch();renderLight();torchSave();sndOfferOnce();\n}''')

# ---- the Overview in the order of play: the town where the evening starts, then who lives below ----
a = p.s.index("    if(m.town){const t=m.town;\n      h+='<div class=\"klabel\">'+esc(t.name)+', the last town</div>';")
b = p.s.index("</div></div>';}\n", a) + len("</div></div>';}\n")
town = p.s[a:b].replace("', the last town</div>';", "', the last town'+(dm?': where the evening starts':'')+'</div>';")
p.s = p.s[:a] + p.s[b:]
anchor = "    if(m.factions.length&&S.role!==\"player\"){h+='<div class=\"klabel\">Factions</div>';"
if p.s.count(anchor) != 1: sys.exit('PATCH STOP: factions anchor')
pace = '''    if(dm){const withThings=m.rooms.filter(r=>r.enc).length, hours=m.rooms.length/4;
      h+='<div class="tiny" style="margin-top:8px">'+m.rooms.length+' rooms, with creatures in '+withThings+' of them. A rough guide to length: about fifteen minutes a room, so '+(hours<=2.5?'one evening':hours<=4.5?'one long evening or two short ones':'two or three evenings')+'. A Small dungeon fits one sitting.</div>';}
'''
p.s = p.s.replace(anchor, pace + town + anchor); p.n += 1
p.save()
